import{_ as l,o as t,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2018-May-24 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-May-24 :: Ceph Performance Weekly","date":"2018-05-28T00:00:00.000Z","updated":"2018-05-28T00:00:00.000Z","tags":["Ceph","Performance Optimization","Pull Requests","Memory Usage","BlueStore","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-May-24_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-May-24_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2018/2018-May-24_-_-_Ceph_Performance_Weekly.md"};function a(_,e,i,p,n,c){return t(),o("div",null,[...e[0]||(e[0]=[s("<p>本次会议主要讨论了Ceph项目的Pull Requests、性能优化和其他相关议题。</p><p><strong>一、Pull Requests讨论</strong></p><ol><li>会议对多个Pull Requests进行了评审和讨论，包括单调时钟切换、加密解密调用更改、日志子系统缓冲写入、新的位图分配器、散列技巧修复、旧版AES密钥处理器清理、定期丢弃功能、Chabot工作重新设计、使用2的幂次优化配置选项和性能等。</li><li>讨论了Power of Two优化，认为其对性能提升具有潜力，并建议将其作为配置选项强制实施。</li></ol><p><strong>二、性能优化</strong></p><ol><li>讨论了将数据同时写入HDD和SSD以提高性能的方案，并在测试中实现了30%的性能提升。</li><li>分析了BlueStore缓存和其他组件的内存使用情况，并针对内存泄漏和碎片化问题进行了讨论。</li><li>讨论了RocksDB缓存的内存使用情况和优化方案。</li><li>讨论了内存分配器优化和碎片化问题，并考虑使用不同的内存池来分配内存。</li></ol><p><strong>三、其他议题</strong></p><ol><li>讨论了使用C++锁优化和编译器支持的锁优化方案。</li><li>讨论了BlueFS文件写入的缓冲区循环和优化方案。</li></ol><p><strong>四、行动计划</strong></p><ol><li>对Pull Requests进行评审和合并。</li><li>对性能优化方案进行测试和评估。</li><li>对内存使用和分配器问题进行进一步分析和优化。</li><li>对锁优化方案进行实施和测试。</li></ol><p><strong>五、后续会议</strong></p><p>下次会议将讨论性能优化方案的测试结果和内存分配器优化方案的实施情况。</p>",11)])])}const d=l(r,[["render",a]]);export{m as __pageData,d as default};
